import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guides/quick-start.md","filePath":"guides/quick-start.md","lastUpdated":1790952322000}'),r={name:"guides/quick-start.md"};function n(i,e,l,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>One complete tutorial from zero: install the app, sign in, create your first bot, give it real work, and reach it from a chat platform. It takes about fifteen minutes.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A computer running macOS, Windows, or Linux.</li><li>A <a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> account — you can create one during sign-in.</li></ul><p>That is all. Memoh Cloud comes with hosted models (DeepSeek, Kimi, GPT, Claude, and more), so you do not need an API key to start.</p><h2 id="step-1-install-memoh" tabindex="-1">Step 1: Install Memoh <a class="header-anchor" href="#step-1-install-memoh" aria-label="Permalink to &quot;Step 1: Install Memoh&quot;">​</a></h2><p>Download the app for your platform from the <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">download page</a> — macOS (DMG), Windows (installer), or Linux (AppImage/deb/rpm) — and open it.</p><h2 id="step-2-sign-in" tabindex="-1">Step 2: Sign in <a class="header-anchor" href="#step-2-sign-in" aria-label="Permalink to &quot;Step 2: Sign in&quot;">​</a></h2><p>On the connect screen, choose <strong>Memoh Cloud</strong> and sign in, or create an account.</p><h2 id="step-3-create-your-first-bot" tabindex="-1">Step 3: Create your first bot <a class="header-anchor" href="#step-3-create-your-first-bot" aria-label="Permalink to &quot;Step 3: Create your first bot&quot;">​</a></h2><p>Go to <strong>Bots → New Bot</strong>, give it a name and display name, then select its chat model on the <strong>General</strong> tab. Hosted models are ready to use.</p><p>Now write its instructions. This step matters most, and it is where people most often go wrong — usually by being too vague. Describe one job clearly:</p><blockquote><p><strong>Name:</strong> Digest</p><p><strong>Role:</strong> Weekly reading digest</p><p><strong>Instructions:</strong> Collect the articles I send you during the week. Every Friday, produce a digest grouped by theme: one sentence per article with its original link, followed by a &quot;worth re-reading&quot; section. Keep original links unchanged. Never publish anything publicly.</p></blockquote><p>A bot with one focused job accumulates far more useful context than a bot that does everything. When work genuinely splits into separate roles, create another bot instead of overloading this one — each bot has its own workspace, memory, and configuration. For a walkthrough of every tab, see <a href="./working-with-bots.html">Bot</a>.</p><p>Click <strong>Chat</strong> and say hello. A reply confirms the model path works.</p><h2 id="bring-your-own-key-byok" tabindex="-1">Bring Your Own Key (BYOK) <a class="header-anchor" href="#bring-your-own-key-byok" aria-label="Permalink to &quot;Bring Your Own Key (BYOK)&quot;">​</a></h2><p>Hosted models aside, you can bring your own models at any time:</p><ol><li>Open <strong>Providers</strong> in the sidebar and click <strong>Add Provider</strong>.</li><li>Pick a template (OpenAI, Anthropic, Gemini, DeepSeek, Zhipu, OpenRouter, Ollama, and others) and paste your API key; for OpenAI-compatible endpoints, add the base URL as well.</li><li>Open the provider and <strong>sync</strong> its model list, or add at least one chat model manually, then switch to it on the bot&#39;s <strong>General</strong> tab.</li></ol><p>BYOK usage is billed by your provider at its own rates. The same idea applies to coding agents: on the bot&#39;s <strong>Agent</strong> tab, sign in to Claude Code or Codex with your own subscription or API key. Provider-specific fields and notes are in <a href="./../integrations/providers/llm.html">LLM Providers</a>.</p><h2 id="step-4-give-it-a-task" tabindex="-1">Step 4: Give it a task <a class="header-anchor" href="#step-4-give-it-a-task" aria-label="Permalink to &quot;Step 4: Give it a task&quot;">​</a></h2><p>A good first request answers five questions:</p><table tabindex="0"><thead><tr><th>Element</th><th>The question it answers</th></tr></thead><tbody><tr><td><strong>Outcome</strong></td><td>What should exist when this is done?</td></tr><tr><td><strong>Source</strong></td><td>Which files, sites, or conversations are relevant?</td></tr><tr><td><strong>Constraints</strong></td><td>What must it avoid, and what needs your approval?</td></tr><tr><td><strong>Format</strong></td><td>How should the answer be delivered?</td></tr><tr><td><strong>Checkpoint</strong></td><td>When should it stop and confirm with you?</td></tr></tbody></table><p>For a result in minutes with no external logins, upload a document and try:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Summarize this document into five key points. In a separate section, list every</span></span>
<span class="line"><span>date, decision, and open question, noting which page or section each came from.</span></span>
<span class="line"><span>Do not modify the original file.</span></span></code></pre></div><p>The bot reads the file inside its own workspace and writes the result back to the conversation. Everything it produces stays in the workspace, where you can browse and edit it under <a href="./files.html">Files</a>.</p><h2 id="step-5-let-it-use-the-workspace-and-browser" tabindex="-1">Step 5: Let it use the workspace and browser <a class="header-anchor" href="#step-5-let-it-use-the-workspace-and-browser" aria-label="Permalink to &quot;Step 5: Let it use the workspace and browser&quot;">​</a></h2><p>The workspace is where a bot does its work. It has a Linux filesystem, a terminal, and a preinstalled toolchain (Python, Node.js, uv, npm), so it can run data cleanups, scripts, and builds directly:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Remove every row with an empty email column from the CSV I just uploaded.</span></span>
<span class="line"><span>Give me the cleaned file and tell me how many rows you dropped.</span></span></code></pre></div><p>When a task needs a real browser — a site that breaks in headless mode, or a page behind a login — enable the visible desktop on the bot&#39;s <strong>Desktop</strong> tab. Once started, the bot drives a headed Chrome and you can watch it work in the desktop panel.</p><p>When it hits a login wall, take over the screen yourself: type the password, passkey, or one-time code, then hand control back. The browser session stays in that workspace, so later tasks remain signed in.</p><div class="warning custom-block"><p class="custom-block-title">Grant access deliberately</p><p>Workspace access is tiered: chat only, read files, write files, execute commands, and manage the container. Grant the level the job needs and no more. See <a href="./access.html">Access Control</a>.</p></div><p>For details, see <a href="./container.html">Workspace</a> and <a href="./browser-computer-use.html">Browser / Computer Use</a>.</p><h2 id="step-6-reach-it-from-a-chat-platform" tabindex="-1">Step 6: Reach it from a chat platform <a class="header-anchor" href="#step-6-reach-it-from-a-chat-platform" aria-label="Permalink to &quot;Step 6: Reach it from a chat platform&quot;">​</a></h2><p>A bot is most useful where you already talk.</p><ol><li>Open the bot&#39;s <strong>Platforms</strong> tab and click <strong>Add</strong>.</li><li>Choose a platform — Telegram, Slack, Discord, Feishu, DingTalk, WeCom, WeChat, QQ, or LINE — and paste that platform&#39;s credentials.</li><li>Message it from that platform. The first message creates a session; send <code>/help</code> to see the available <a href="./slash-commands.html">slash commands</a>.</li></ol><p>From then on you can hand off a task from your phone and collect the result in the same conversation. For per-platform setup, see <a href="./../integrations/channels/">Channels</a>.</p><h2 id="step-7-review-then-make-it-stick" tabindex="-1">Step 7: Review, then make it stick <a class="header-anchor" href="#step-7-review-then-make-it-stick" aria-label="Permalink to &quot;Step 7: Review, then make it stick&quot;">​</a></h2><p>When something is not right, say so. Phrase corrections as durable rules rather than one-off fixes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For all future digests, use this format: grouped by theme, one line per article,</span></span>
<span class="line"><span>links inline, and a &quot;worth re-reading&quot; section at the end.</span></span></code></pre></div><p>Once a routine is stable, stop retyping it:</p><ul><li>Save it as a <a href="./skills.html">Skill</a> so one sentence invokes the whole routine.</li><li>Turn it into a <a href="./schedule.html">Scheduled Task</a> that runs on cron with no chat at all.</li><li>Use <a href="./memory.html">Memory</a> to carry your preferences and project context into every future session.</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Read</th></tr></thead><tbody><tr><td>Configure a bot tab by tab</td><td><a href="./working-with-bots.html">Bot</a></td></tr><tr><td>Understand chat, discuss, and routing</td><td><a href="./sessions.html">Sessions</a></td></tr><tr><td>Run scheduled or recurring tasks</td><td><a href="./schedule.html">Schedule</a></td></tr><tr><td>Connect external tools and data</td><td><a href="./mcp.html">MCP</a>, <a href="./connectors.html">Connectors</a></td></tr><tr><td>Install prebuilt capabilities</td><td><a href="./supermarket.html">Supermarket</a></td></tr><tr><td>Hook into lifecycle events</td><td><a href="./hooks.html">Hooks</a></td></tr><tr><td>Control who can talk to the bot</td><td><a href="./access.html">Access Control</a></td></tr><tr><td>See what others run</td><td><a href="./use-cases.html">Use Cases</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Need help?</p><p>Questions about plans, credits, or your account — or anything this site doesn&#39;t cover — are answered in the <a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Help Center</a>, where you can also reach the Memoh team.</p></div>`,44)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
